/** EdgeOne request metadata (same shape as the agent eo).
 * EdgeOne 请求元数据（与 agent 模型的 eo 形状对齐）。 */
export interface EdgeFunctionEoContext {
    /** Geo info.
     * 地理信息。 */
    geo: Record<string, unknown>;
    /** Client IP.
     * 客户端 IP。 */
    clientIp: string;
}
/** Route params: single-segment string, multi-segment string[].
 * 路由参数：单段动态参数为 string，多段 [[...]] 为 string[]。 */
export interface EdgeFunctionParams {
    [key: string]: string | string[];
}
/**
 * Edge function handler context (parameter of `onRequest(context)`).
 * Edge 函数 handler 的上下文（`onRequest(context)` 的入参）。
 */
export interface EdgeFunctionContext {
    /** Web-standard Request.
     * Web 标准 Request。 */
    request: Request;
    /** Route params.
     * 路由参数。 */
    params: EdgeFunctionParams;
    /** Function environment variables.
     * 函数环境变量。 */
    env: Record<string, string | undefined>;
    /** Keep an async task alive (non-blocking).
     * 等待异步任务（不阻塞响应）。 */
    waitUntil?: (promise: Promise<unknown>) => void;
    /** EdgeOne request metadata.
     * EdgeOne 请求元数据。 */
    eo: EdgeFunctionEoContext;
}
/** Edge function handler; must return a Web Response.
 * Edge 函数 handler，必须返回 Web Response。 */
export type EdgeFunctionHandler = (context: EdgeFunctionContext) => Response | Promise<Response>;
/**
 * Edge middleware (Next.js-style `middleware.js/ts`) context.
 * Edge 中间件（Next.js 风格 `middleware.js/ts`）context。
 */
export interface EdgeMiddlewareContext {
    /** Web-standard Request.
     * Web 标准 Request。 */
    request: Request;
    /** Parsed URL.
     * 解析后的 URL。 */
    urlInfo: URL;
    /** Function environment variables.
     * 函数环境变量。 */
    env: Record<string, string | undefined>;
    /** Keep an async task alive (non-blocking).
     * 等待异步任务（不阻塞响应）。 */
    waitUntil?: (promise: Promise<unknown>) => void;
    /** Platform hook context (internal), usually not needed.
     * 平台 hook 上下文（内部透传），通常无需使用。 */
    hookCtx?: unknown;
}
/**
 * Edge middleware handler. Return a Response, or null to continue downstream;
 * use `x-middleware-next` / `x-middleware-rewrite` response headers to control flow.
 * Edge 中间件 handler。返回 Response 或 null（继续执行下游）；
 * 可通过响应头 `x-middleware-next` / `x-middleware-rewrite` 控制流转。
 */
export type EdgeMiddlewareHandler = (context: EdgeMiddlewareContext) => Response | null | undefined | Promise<Response | null | undefined>;
/** Edge middleware config: `export const config = { matcher }`.
 * Edge 中间件配置：`export const config = { matcher }`。 */
export interface EdgeMiddlewareConfig {
    /** Paths to match.
     * 匹配路径。 */
    matcher: string | string[];
}
